// Generated by the Firenook console from saved Storage rules tests.
// 6 tests against storage.rules.
// Run with the Storage emulator up, for example:
//   firebase emulators:exec --only storage "npx vitest run"
// Firestore documents the rules read with firestore.get() or firestore.exists()
// are not set up here; add them in beforeEach when a test depends on one.
import { readFileSync } from 'node:fs'
import { afterAll, beforeAll, beforeEach, test } from 'vitest'
import {
  assertFails,
  assertSucceeds,
  initializeTestEnvironment,
  type RulesTestEnvironment,
} from '@firebase/rules-unit-testing'
import {
  deleteObject,
  getMetadata,
  listAll,
  ref,
  updateMetadata,
  uploadBytes,
} from 'firebase/storage'

let env: RulesTestEnvironment

beforeAll(async () => {
  env = await initializeTestEnvironment({
    projectId: "demo-firenook-rules-testing",
    storage: { rules: readFileSync("storage.rules", 'utf8') },
  })
})

afterAll(() => env.cleanup())
beforeEach(() => env.clearStorage())

test("alice uploads to her folder is allowed", async () => {
  const storage = env.authenticatedContext("alice", {}).storage("gs://demo-firenook-rules-testing.appspot.com")
  await assertSucceeds(uploadBytes(ref(storage, "users/alice/notes.txt"), new Uint8Array(16), { contentType: "text/plain" }))
})

test("bob reads alice is denied", async () => {
  await env.withSecurityRulesDisabled(async (context) => {
    const storage = context.storage("gs://demo-firenook-rules-testing.appspot.com")
    await uploadBytes(ref(storage, "users/alice/notes.txt"), new Uint8Array(16), { contentType: "image/png" })
  })
  const storage = env.authenticatedContext("bob", {}).storage("gs://demo-firenook-rules-testing.appspot.com")
  await assertFails(getMetadata(ref(storage, "users/alice/notes.txt")))
})

test("signed out reads alice is denied", async () => {
  await env.withSecurityRulesDisabled(async (context) => {
    const storage = context.storage("gs://demo-firenook-rules-testing.appspot.com")
    await uploadBytes(ref(storage, "users/alice/notes.txt"), new Uint8Array(16), { contentType: "image/png" })
  })
  const storage = env.unauthenticatedContext().storage("gs://demo-firenook-rules-testing.appspot.com")
  await assertFails(getMetadata(ref(storage, "users/alice/notes.txt")))
})

test("signed out reads a public file is allowed", async () => {
  await env.withSecurityRulesDisabled(async (context) => {
    const storage = context.storage("gs://demo-firenook-rules-testing.appspot.com")
    await uploadBytes(ref(storage, "public/logo.png"), new Uint8Array(16), { contentType: "image/png" })
  })
  const storage = env.unauthenticatedContext().storage("gs://demo-firenook-rules-testing.appspot.com")
  await assertSucceeds(getMetadata(ref(storage, "public/logo.png")))
})

test("alice lists her folder is allowed", async () => {
  const storage = env.authenticatedContext("alice", {}).storage("gs://demo-firenook-rules-testing.appspot.com")
  await assertSucceeds(listAll(ref(storage, "users/alice/")))
})

test("signed out lists alice is denied", async () => {
  const storage = env.unauthenticatedContext().storage("gs://demo-firenook-rules-testing.appspot.com")
  await assertFails(listAll(ref(storage, "users/alice/")))
})
